40	/**
41	 * Miscellaneous collection utility methods.
42	 * Mainly for internal use within the framework.
43	 *
44	 * @since 2.0.7
45	 */
46	public class CollectionUtils {
47	
48	    private static final Comparator<String> SIMPLE_NAME_COMPARATOR = (s1, s2) -> {
49	        if (s1 == null && s2 == null) {
50	            return 0;
51	        }
52	        if (s1 == null) {
53	            return -1;
54	        }
55	        if (s2 == null) {
56	            return 1;
57	        }
58	        int i1 = s1.lastIndexOf('.');
59	        if (i1 >= 0) {
60	            s1 = s1.substring(i1 + 1);
61	        }
62	        int i2 = s2.lastIndexOf('.');
63	        if (i2 >= 0) {
64	            s2 = s2.substring(i2 + 1);
65	        }
66	        return s1.compareToIgnoreCase(s2);
67	    };
68	
69	    private CollectionUtils() {}
70	
71	    public static <T extends Comparable<? super T>> List<T> sort(List<T> list) {
72	        if (isNotEmpty(list)) {
73	            Collections.sort(list);
74	        }
75	        return list;
76	    }
77	
78	    public static List<String> sortSimpleName(List<String> list) {
79	        if (list != null && list.size() > 0) {
80	            Collections.sort(list, SIMPLE_NAME_COMPARATOR);
81	        }
82	        return list;
83	    }
84	
85	    /**
86	     * Flip the specified {@link Map}
87	     *
88	     * @param map The specified {@link Map},Its value must be unique
89	     * @param <K> The key type of specified {@link Map}
90	     * @param <V> The value type of specified {@link Map}
91	     * @return {@link Map}
92	     */
93	    @SuppressWarnings("unchecked")
94	    public static <K, V> Map<V, K> flip(Map<K, V> map) {
95	        if (isEmptyMap(map)) {
96	            return (Map<V, K>) map;
97	        }
98	        Set<V> set = new HashSet<>(map.values());
99	        if (set.size() != map.size()) {
100	            throw new IllegalArgumentException("The map value must be unique.");
101	        }
102	        return map.entrySet().stream().collect(Collectors.toMap(Map.Entry::getValue, Map.Entry::getKey));
103	    }
104	
105	    public static Map<String, Map<String, String>> splitAll(Map<String, List<String>> list, String separator) {
106	        if (list == null) {
107	            return null;
108	        }
109	        Map<String, Map<String, String>> result = new HashMap<>();
110	        for (Map.Entry<String, List<String>> entry : list.entrySet()) {
111	            result.put(entry.getKey(), split(entry.getValue(), separator));
112	        }
113	        return result;
114	    }
115	
116	    public static Map<String, List<String>> joinAll(Map<String, Map<String, String>> map, String separator) {
117	        if (map == null) {
118	            return null;
119	        }
120	        Map<String, List<String>> result = new HashMap<>();
121	        for (Map.Entry<String, Map<String, String>> entry : map.entrySet()) {
122	            result.put(entry.getKey(), join(entry.getValue(), separator));
123	        }
124	        return result;
125	    }
126	
127	    public static Map<String, String> split(List<String> list, String separator) {
128	        if (list == null) {
129	            return null;
130	        }
131	        Map<String, String> map = new HashMap<>();
132	        if (list.isEmpty()) {
133	            return map;
134	        }
135	        for (String item : list) {
136	            int index = item.indexOf(separator);
137	            if (index == -1) {
138	                map.put(item, "");
139	            } else {
140	                map.put(item.substring(0, index), item.substring(index + 1));
141	            }
142	        }
143	        return map;
144	    }
145	
146	    public static List<String> join(Map<String, String> map, String separator) {
147	        if (map == null) {
148	            return null;
149	        }
150	        List<String> list = new ArrayList<>();
151	        if (map.size() == 0) {
152	            return list;
153	        }
154	        for (Map.Entry<String, String> entry : map.entrySet()) {
155	            String key = entry.getKey();
156	            String value = entry.getValue();
157	            if (StringUtils.isEmpty(value)) {
158	                list.add(key);
159	            } else {
160	                list.add(key + separator + value);
161	            }
162	        }
163	        return list;
164	    }
165	
166	    public static String join(List<String> list, String separator) {
167	        StringBuilder sb = new StringBuilder();
168	        for (String ele : list) {
169	            if (sb.length() > 0) {
170	                sb.append(separator);
171	            }
172	            sb.append(ele);
173	        }
174	        return sb.toString();
175	    }
176	
177	    public static boolean mapEquals(Map<?, ?> map1, Map<?, ?> map2) {
178	        if (map1 == null && map2 == null) {
179	            return true;
180	        }
181	        if (map1 == null || map2 == null) {
182	            return false;
183	        }
184	        if (map1.size() != map2.size()) {
185	            return false;
186	        }
187	        for (Map.Entry<?, ?> entry : map1.entrySet()) {
188	            Object key = entry.getKey();
189	            Object value1 = entry.getValue();
190	            Object value2 = map2.get(key);
191	            if (!objectEquals(value1, value2)) {
192	                return false;
193	            }
194	        }
195	        return true;
196	    }
197	
198	    private static boolean objectEquals(Object obj1, Object obj2) {
199	        if (obj1 == null && obj2 == null) {
200	            return true;
201	        }
202	        if (obj1 == null || obj2 == null) {
203	            return false;
204	        }
205	        return obj1.equals(obj2);
206	    }
207	
208	    public static Map<String, String> toStringMap(String... pairs) {
209	        Map<String, String> parameters = new HashMap<>();
210	        if (ArrayUtils.isEmpty(pairs)) {
211	            return parameters;
212	        }
213	
214	        if (pairs.length > 0) {
215	            if (pairs.length % 2 != 0) {
216	                throw new IllegalArgumentException("pairs must be even.");
217	            }
218	            for (int i = 0; i < pairs.length; i = i + 2) {
219	                parameters.put(pairs[i], pairs[i + 1]);
220	            }
221	        }
222	        return parameters;
223	    }
224	
225	    @SuppressWarnings("unchecked")
226	    public static <K, V> Map<K, V> toMap(Object... pairs) {
227	        Map<K, V> ret = new HashMap<>();
228	        if (pairs == null || pairs.length == 0) {
229	            return ret;
230	        }
231	
232	        if (pairs.length % 2 != 0) {
233	            throw new IllegalArgumentException("Map pairs can not be odd number.");
234	        }
235	        int len = pairs.length / 2;
236	        for (int i = 0; i < len; i++) {
237	            ret.put((K) pairs[2 * i], (V) pairs[2 * i + 1]);
238	        }
239	        return ret;
240	    }
241	
242	    @SuppressWarnings("unchecked")
243	    public static <K, V> Map<K, V> objToMap(Object object) throws IllegalAccessException {
244	        Map<K, V> ret = new HashMap<>();
245	        if (object != null) {
246	            Field[] fields = object.getClass().getDeclaredFields();
247	            for (Field field : fields) {
248	                field.setAccessible(true);
249	                Object value = field.get(object);
250	                if (value != null) {
251	                    ret.put((K) field.getName(), (V) value);
252	                }
253	            }
254	        }
255	        return ret;
256	    }
