136	    /**
137	     * <p>Repeat a String {@code repeat} times to form a
138	     * new String.</p>
139	     *
140	     * <pre>
141	     * StringUtils.repeat(null, 2) = null
142	     * StringUtils.repeat("", 0)   = ""
143	     * StringUtils.repeat("", 2)   = ""
144	     * StringUtils.repeat("a", 3)  = "aaa"
145	     * StringUtils.repeat("ab", 2) = "abab"
146	     * StringUtils.repeat("a", -2) = ""
147	     * </pre>
148	     *
149	     * @param str    the String to repeat, may be null
150	     * @param repeat number of times to repeat str, negative treated as zero
151	     * @return a new String consisting of the original String repeated,
152	     * {@code null} if null String input
153	     */
154	    public static String repeat(final String str, final int repeat) {
155	        // Performance tuned for 2.0 (JDK1.4)
156	
157	        if (str == null) {
158	            return null;
159	        }
160	        if (repeat <= 0) {
161	            return EMPTY_STRING;
162	        }
163	        final int inputLength = str.length();
164	        if (repeat == 1 || inputLength == 0) {
165	            return str;
166	        }
167	        if (inputLength == 1 && repeat <= PAD_LIMIT) {
168	            return repeat(str.charAt(0), repeat);
169	        }
170	
171	        final int outputLength = inputLength * repeat;
172	        switch (inputLength) {
173	            case 1:
174	                return repeat(str.charAt(0), repeat);
175	            case 2:
176	                final char ch0 = str.charAt(0);
177	                final char ch1 = str.charAt(1);
178	                final char[] output2 = new char[outputLength];
179	                for (int i = repeat * 2 - 2; i >= 0; i--, i--) {
180	                    output2[i] = ch0;
181	                    output2[i + 1] = ch1;
182	                }
183	                return new String(output2);
184	            default:
185	                final StringBuilder buf = new StringBuilder(outputLength);
186	                for (int i = 0; i < repeat; i++) {
187	                    buf.append(str);
188	                }
189	                return buf.toString();
190	        }
191	    }
