193	    /**
194	     * <p>Repeat a String {@code repeat} times to form a
195	     * new String, with a String separator injected each time. </p>
196	     *
197	     * <pre>
198	     * StringUtils.repeat(null, null, 2) = null
199	     * StringUtils.repeat(null, "x", 2)  = null
200	     * StringUtils.repeat("", null, 0)   = ""
201	     * StringUtils.repeat("", "", 2)     = ""
202	     * StringUtils.repeat("", "x", 3)    = "xxx"
203	     * StringUtils.repeat("?", ", ", 3)  = "?, ?, ?"
204	     * </pre>
205	     *
206	     * @param str       the String to repeat, may be null
207	     * @param separator the String to inject, may be null
208	     * @param repeat    number of times to repeat str, negative treated as zero
209	     * @return a new String consisting of the original String repeated,
210	     * {@code null} if null String input
211	     * @since 2.5
212	     */
213	    public static String repeat(final String str, final String separator, final int repeat) {
214	        if (str == null || separator == null) {
215	            return repeat(str, repeat);
216	        }
217	        // given that repeat(String, int) is quite optimized, better to rely on it than try and splice this into it
218	        final String result = repeat(str + separator, repeat);
219	        return removeEnd(result, separator);
220	    }
