222	    /**
223	     * <p>Removes a substring only if it is at the end of a source string,
224	     * otherwise returns the source string.</p>
225	     *
226	     * <p>A {@code null} source string will return {@code null}.
227	     * An empty ("") source string will return the empty string.
228	     * A {@code null} search string will return the source string.</p>
229	     *
230	     * <pre>
231	     * StringUtils.removeEnd(null, *)      = null
232	     * StringUtils.removeEnd("", *)        = ""
233	     * StringUtils.removeEnd(*, null)      = *
234	     * StringUtils.removeEnd("www.domain.com", ".com.")  = "www.domain.com"
235	     * StringUtils.removeEnd("www.domain.com", ".com")   = "www.domain"
236	     * StringUtils.removeEnd("www.domain.com", "domain") = "www.domain.com"
237	     * StringUtils.removeEnd("abc", "")    = "abc"
238	     * </pre>
239	     *
240	     * @param str    the source String to search, may be null
241	     * @param remove the String to search for and remove, may be null
242	     * @return the substring with the string removed if found,
243	     * {@code null} if null String input
244	     */
245	    public static String removeEnd(final String str, final String remove) {
246	        if (isAnyEmpty(str, remove)) {
247	            return str;
248	        }
249	        if (str.endsWith(remove)) {
250	            return str.substring(0, str.length() - remove.length());
251	        }
252	        return str;
253	    }
254	
255	    /**
256	     * <p>Returns padding using the specified delimiter repeated
257	     * to a given length.</p>
258	     *
259	     * <pre>
260	     * StringUtils.repeat('e', 0)  = ""
261	     * StringUtils.repeat('e', 3)  = "eee"
262	     * StringUtils.repeat('e', -2) = ""
263	     * </pre>
264	     *
265	     * <p>Note: this method doesn't not support padding with
266	     * <a href="http://www.unicode.org/glossary/#supplementary_character">Unicode Supplementary Characters</a>
267	     * as they require a pair of {@code char}s to be represented.
268	     * If you are needing to support full I18N of your applications
269	     * consider using {@link #repeat(String, int)} instead.
270	     * </p>
271	     *
272	     * @param ch     character to repeat
273	     * @param repeat number of times to repeat char, negative treated as zero
274	     * @return String with repeated character
275	     * @see #repeat(String, int)
276	     */
277	    public static String repeat(final char ch, final int repeat) {
278	        final char[] buf = new char[repeat];
279	        for (int i = repeat - 1; i >= 0; i--) {
280	            buf[i] = ch;
281	        }
282	        return new String(buf);
283	    }
284	
285	    /**
