                }
                break;
            case 5:
                if ("false".equalsIgnoreCase(value)) {
                    return Boolean.FALSE;
                }
                break;
            default:
        }
        return null;
    }

    public static boolean toBoolean(String value, boolean defaultValue) {
        Boolean result = toBoolean(value);
        return result == null ? defaultValue : result;
    }
